create policy "Anyone can view menu images" on storage.objects for select to anon, authenticated using (bucket_id = 'menu-images');
create policy "Kitchen uploads menu images" on storage.objects for insert to authenticated with check (bucket_id = 'menu-images' and public.has_role(auth.uid(), 'admin'));
create policy "Kitchen updates menu images" on storage.objects for update to authenticated using (bucket_id = 'menu-images' and public.has_role(auth.uid(), 'admin'));
create policy "Kitchen deletes menu images" on storage.objects for delete to authenticated using (bucket_id = 'menu-images' and public.has_role(auth.uid(), 'admin'));